html:
{% set groups = {} %}
{% for it in doc.items %}
  {% set g = groups.setdefault(it.item_code, {"name": it.item_name, "uom": it.uom or it.stock_uom, "qty": 0, "batches": {}}) %}
  {% if g.update({"qty": g["qty"] + it.qty}) %}{% endif %}
  {% set batch_rows = [] %}
  {% if it.serial_and_batch_bundle %}
    {% for be in frappe.get_all("Serial and Batch Entry", filters={"parent": it.serial_and_batch_bundle}, fields=["batch_no", "qty"]) %}
      {% if be.batch_no %}{% if batch_rows.append((be.batch_no, be.qty|abs)) %}{% endif %}{% endif %}
    {% endfor %}
  {% elif it.batch_no %}
    {% if batch_rows.append((it.batch_no, it.qty)) %}{% endif %}
  {% endif %}
  {% for bno, bqty in batch_rows %}
    {% if g["batches"].update({bno: g["batches"].get(bno, 0) + bqty}) %}{% endif %}
  {% endfor %}
{% endfor %}

<div style="font-family: sans-serif;">
  <h3 style="text-align:center; margin-bottom: 2px;">PACKING LIST</h3>
  <p style="text-align:center; margin-top:0;">{{ doc.company }}</p>
  <table style="width:100%; font-size: 12px; margin-bottom: 10px;">
    <tr>
      <td><b>Packing List / DN:</b> {{ doc.name }}</td>
      <td><b>Date:</b> {{ frappe.utils.formatdate(doc.posting_date) }}</td>
    </tr>
    <tr>
      <td><b>Customer:</b> {{ doc.customer_name or doc.customer }}</td>
      <td><b>Sales Order:</b> {{ doc.items[0].against_sales_order or "" }}</td>
    </tr>
  </table>

  <table class="table table-bordered" style="width:100%; font-size: 12px;">
    <thead>
      <tr style="background:#f0f0f0;">
        <th style="width:5%;">#</th>
        <th style="width:20%;">Item</th>
        <th style="width:32%;">Item Name</th>
        <th style="width:23%;">Batch No(s)</th>
        <th style="width:12%; text-align:right;">Total Qty</th>
        <th style="width:8%;">UOM</th>
      </tr>
    </thead>
    <tbody>
      {% for code, g in groups.items() %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ code }}</td>
        <td>{{ g["name"] }}</td>
        <td>
          {% if g["batches"] %}
            {% for bno, bqty in g["batches"].items() %}{{ bno }} ({{ frappe.utils.flt(bqty, 2) }}){% if not loop.last %}<br>{% endif %}{% endfor %}
          {% else %}&mdash;{% endif %}
        </td>
        <td style="text-align:right;"><b>{{ frappe.utils.flt(g["qty"], 2) }}</b></td>
        <td>{{ g["uom"] }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>
  <p style="font-size:11px; color:#666;">Each item is one consolidated line; the batch split is shown against it.</p>
  <br><br>
  <table style="width:100%; font-size: 12px;">
    <tr>
      <td style="width:50%;">Packed / Checked By: ______________</td>
      <td style="width:50%; text-align:right;">Authorised Signatory: ______________</td>
    </tr>
  </table>
</div>
